CREATE TABLE public.ai_daily_usage (user_id uuid NOT NULL, local_day date NOT NULL, used integer NOT NULL DEFAULT 0 CHECK (used BETWEEN 0 AND 5), PRIMARY KEY(user_id,local_day));
GRANT SELECT ON public.ai_daily_usage TO authenticated;
GRANT ALL ON public.ai_daily_usage TO service_role;
ALTER TABLE public.ai_daily_usage ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_read ON public.ai_daily_usage FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.is_allowlisted());
CREATE OR REPLACE FUNCTION public.has_pro_access(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE((SELECT status IN ('active','trialing','past_due','canceled') AND (current_period_end IS NULL OR current_period_end>now()) FROM public.subscriptions WHERE user_id=p_user ORDER BY created_at DESC LIMIT 1),false) $$;
REVOKE ALL ON FUNCTION public.has_pro_access(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_pro_access(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.coach_local_day(p_user uuid) RETURNS date LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (now() AT TIME ZONE COALESCE((SELECT CASE WHEN timezone IN (SELECT name FROM pg_timezone_names) THEN timezone ELSE 'UTC' END FROM public.user_profiles WHERE user_id=p_user),'UTC'))::date $$;
REVOKE ALL ON FUNCTION public.coach_local_day(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.coach_local_day(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.get_daily_coach_used() RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.is_allowlisted() THEN COALESCE((SELECT used FROM public.ai_daily_usage WHERE user_id=auth.uid() AND local_day=public.coach_local_day(auth.uid())),0) ELSE NULL END $$;
REVOKE ALL ON FUNCTION public.get_daily_coach_used() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_daily_coach_used() TO authenticated;
CREATE OR REPLACE FUNCTION public.consume_daily_coach_credit() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result integer; BEGIN IF auth.uid() IS NULL OR NOT public.is_allowlisted() THEN RAISE EXCEPTION 'Forbidden'; END IF; IF public.has_pro_access(auth.uid()) THEN RETURN 0; END IF; INSERT INTO public.ai_daily_usage(user_id,local_day,used) VALUES(auth.uid(),public.coach_local_day(auth.uid()),1) ON CONFLICT(user_id,local_day) DO UPDATE SET used=ai_daily_usage.used+1 WHERE ai_daily_usage.used<5 RETURNING used INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.consume_daily_coach_credit() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.consume_daily_coach_credit() TO authenticated;
CREATE TABLE public.study_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, feature text NOT NULL CHECK(feature IN ('exam','signs','intersections','substances','speed','simulation','review')), state text NOT NULL, free_slot boolean NOT NULL, payload jsonb NOT NULL, answers jsonb NOT NULL DEFAULT '[]', completed boolean NOT NULL DEFAULT false, score integer, average_reaction double precision, version integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.study_attempts TO authenticated;
GRANT ALL ON public.study_attempts TO service_role;
ALTER TABLE public.study_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_read ON public.study_attempts FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.is_allowlisted());
CREATE UNIQUE INDEX one_free_study_slot ON public.study_attempts(user_id,feature) WHERE free_slot;
CREATE INDEX study_attempt_history ON public.study_attempts(user_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.reserve_study_attempt(p_user uuid,p_feature text,p_state text,p_payload jsonb) RETURNS public.study_attempts LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.study_attempts; pro boolean; BEGIN IF NOT EXISTS(SELECT 1 FROM public.app_allowlist a JOIN auth.users u ON lower(u.email)=a.email WHERE u.id=p_user) THEN RAISE EXCEPTION 'Forbidden'; END IF; pro:=public.has_pro_access(p_user); IF p_feature='review' AND NOT pro THEN RAISE EXCEPTION 'Review missed questions is Pro only'; END IF; IF NOT pro THEN SELECT * INTO result FROM public.study_attempts WHERE user_id=p_user AND feature=p_feature AND free_slot; IF FOUND THEN RETURN result; END IF; END IF; INSERT INTO public.study_attempts(user_id,feature,state,free_slot,payload) VALUES(p_user,p_feature,p_state,NOT pro,p_payload) ON CONFLICT(user_id,feature) WHERE free_slot DO NOTHING RETURNING * INTO result; IF result.id IS NULL THEN SELECT * INTO result FROM public.study_attempts WHERE user_id=p_user AND feature=p_feature AND free_slot; END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.reserve_study_attempt(uuid,text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reserve_study_attempt(uuid,text,text,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.commit_study_answer(p_id uuid,p_user uuid,p_version integer,p_answer jsonb,p_score integer,p_reaction double precision,p_hub jsonb DEFAULT NULL) RETURNS public.study_attempts LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.study_attempts; BEGIN SELECT * INTO result FROM public.study_attempts WHERE id=p_id AND user_id=p_user FOR UPDATE; IF NOT FOUND OR result.completed OR result.version<>p_version THEN RAISE EXCEPTION 'Attempt changed. Reload to continue.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.app_allowlist a JOIN auth.users u ON lower(u.email)=a.email WHERE u.id=p_user) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF NOT result.free_slot AND NOT public.has_pro_access(p_user) THEN RAISE EXCEPTION 'Pro access required'; END IF; UPDATE public.study_attempts SET answers=answers||jsonb_build_array(p_answer),version=version+1,completed=jsonb_array_length(answers)+1=jsonb_array_length(payload),score=p_score,average_reaction=p_reaction,updated_at=now() WHERE id=p_id RETURNING * INTO result; IF result.completed AND result.feature='exam' THEN INSERT INTO public.mock_test_history(user_id,score_pct,state) VALUES(p_user,p_score,result.state); END IF; IF p_hub IS NOT NULL THEN INSERT INTO public.test_hub_progress(user_id,state,topic,questions,last_score,updated_at) VALUES(p_user,result.state,p_hub->>'topic',p_hub->'questions',CASE WHEN result.completed AND result.feature<>'review' THEN p_score ELSE NULL END,now()) ON CONFLICT(user_id,state,topic) DO UPDATE SET questions=excluded.questions,last_score=COALESCE(excluded.last_score,test_hub_progress.last_score),updated_at=now(); END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.commit_study_answer(uuid,uuid,integer,jsonb,integer,double precision,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.commit_study_answer(uuid,uuid,integer,jsonb,integer,double precision,jsonb) TO service_role;
CREATE POLICY free_exam_server_writes ON public.mock_test_history AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.has_pro_access(auth.uid()));
CREATE POLICY free_exam_no_edit ON public.mock_test_history AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.has_pro_access(auth.uid())) WITH CHECK(public.has_pro_access(auth.uid()));
CREATE POLICY free_exam_no_delete ON public.mock_test_history AS RESTRICTIVE FOR DELETE TO authenticated USING(public.has_pro_access(auth.uid()));
CREATE POLICY free_hub_server_writes ON public.test_hub_progress AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.has_pro_access(auth.uid()));
CREATE POLICY free_hub_no_edit ON public.test_hub_progress AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.has_pro_access(auth.uid())) WITH CHECK(public.has_pro_access(auth.uid()));
CREATE POLICY free_hub_no_delete ON public.test_hub_progress AS RESTRICTIVE FOR DELETE TO authenticated USING(public.has_pro_access(auth.uid()));
COMMENT ON TABLE public.ai_coach_usage IS 'DEPRECATED: daily allowances use ai_daily_usage';
COMMENT ON COLUMN public.user_profiles.free_usage IS 'DEPRECATED: usage is authoritative in ai_daily_usage and study_attempts';